/* ---------- beheer (tab Leeromgeving op de pagina Vaargebieden) ---------- */
function sjView(){if(!APP.sjDb)return'<p class="note warn">'+esc(foutTekst({message:'schema cache'}))+'</p>';
  const st=SJ.st&&STADS.includes(SJ.st)?SJ.st:CITY.id;SJ.st=st;const mods=(APP.meMods||{})[st];
  if(!mods){meLoad(st).then(()=>{if(gbPagina()&&APP.gbTab==='sjablonen')renderGebiedBouwer()});return'<p class="note">Laden…</p>'}
  let h='<div class="row" style="gap:8px;align-items:flex-end;flex-wrap:wrap"><div class="field" style="margin:0"><label for="sjSt">Vaargebied</label><select id="sjSt"'+(SJ.edit?' disabled':'')+'>'+stadOpts(st)+'</select></div>'+(SJ.edit?'':'<button type="button" class="btn primary" data-sj="nieuw">+ Nieuw sjabloon</button>')+'</div>';
  if(SJ.edit)return h+sjEditor(st,mods);
  const sjs=APP.sjAll.filter(s=>s.gebied===st);const kand=APP.roster.filter(r=>r.rol==='kandidaat'&&(r.stad||'amsterdam')===st);
  const telVoor=t=>kand.filter(r=>{const x=sjVan(r);return t?x&&x.id===t.id:!x}).length;
  h+='<p class="note">Een sjabloon bepaalt welke hoofdstukken een kandidaat van '+esc(STAD_NAAM[st]||st)+' in de leeromgeving krijgt, in welke volgorde, en welke extra modules ertussen staan. Toewijzen kan per kandidaat (⋯ → Leeromgeving-sjabloon, of hieronder bij het sjabloon) en per groep. Volgorde: eigen sjabloon, dan dat van de groep, dan de standaard van het gebied.</p>';
  const std=sjs.find(s=>s.standaard);
  h+='<div class="tbl-wrap"><table class="tbl dtbl"><thead><tr><th>Sjabloon</th><th>Inhoud</th><th>Kandidaten</th><th></th></tr></thead><tbody>'+
    (std?'':'<tr><td class="c-person"><b>'+esc(SJ_ALLE)+'</b><br><small>Standaard zolang er geen eigen standaard is</small></td><td data-l="Inhoud">'+LEER_ALL.length+' hoofdstukken</td><td data-l="Kandidaten">'+telVoor(null)+'</td><td class="c-act"><div class="acts"><button type="button" class="btn sm" data-sj="voorbeeld">Voorbeeld</button></div></td></tr>')+
    sjs.map(s=>'<tr><td class="c-person"><b>'+esc(s.naam)+'</b>'+(s.standaard?' <span class="pill ok">Standaard</span>':'')+'</td><td data-l="Inhoud">'+esc(sjSamenvatting(s,mods))+'</td><td data-l="Kandidaten">'+telVoor(s)+'</td><td class="c-act"><div class="acts">'+(s.standaard?'':'<button type="button" class="btn sm" data-sj="std" data-id="'+s.id+'">Standaard maken</button>')+'<button type="button" class="btn sm" data-sj="voorbeeld" data-id="'+s.id+'">Voorbeeld</button><button type="button" class="btn sm primary" data-sj="bewerk" data-id="'+s.id+'">Bewerken</button><button type="button" class="btn sm danger" data-sj="weg" data-id="'+s.id+'">Verwijderen</button></div></td></tr>').join('')+'</tbody></table></div>';
  return h}
function sjEditor(st,mods){const e=SJ.edit;const groepen=(APP.groepen||[]).filter(g=>(g.stad||'amsterdam')===st);
  const kand=APP.roster.filter(r=>r.rol==='kandidaat'&&(r.stad||'amsterdam')===st&&r.status!=='geslaagd').sort((a,b)=>a.naam.localeCompare(b.naam));
  const inLijst=it=>e.items.some(x=>x.t===it.t&&x.id===it.id);
  const vrijH=LEER_ALL.map((c,i)=>({t:'h',id:c.id,n:'Hoofdstuk '+(i+1)+' · '+c.t})).filter(x=>!inLijst(x));
  const vrijM=mods.map(m=>({t:'m',id:m.id,n:m.titel+(m.actief?'':' (concept)')})).filter(x=>!inLijst(x));
  let h='<section class="lsec sjedit" id="sjForm"><div class="lsec-h"><h2>'+(e.id?'Sjabloon bewerken':'Nieuw sjabloon')+' · '+esc(STAD_NAAM[st]||st)+'</h2></div>'+
    '<div class="field"><label for="sjNaam">Naam</label><input id="sjNaam" type="text" maxlength="80" placeholder="Bijvoorbeeld Versneld SOR of Pilot nieuwe schippers" value="'+esc(e.naam)+'"></div>'+
    '<label class="chk"><input type="checkbox" id="sjStd"'+(e.standaard?' checked':'')+'> Standaard voor kandidaten van '+esc(STAD_NAAM[st]||st)+' zonder eigen sjabloon of groepssjabloon</label>'+
    '<h3>Inhoud en volgorde</h3><ol class="sjitems">'+e.items.map((it,k)=>{const nm=sjItemNaam(it,mods);if(!nm)return'';const m=it.t==='m'&&mods.find(x=>x.id===it.id);
      return'<li class="'+(it.t==='m'?'sj-m':'sj-h')+'"><span>'+esc(nm)+(m&&!m.actief?' <span class="pill warn">Concept: kandidaten zien hem pas als hij actief is</span>':'')+'</span><span class="acts"><button type="button" class="btn sm" data-sj="op" data-k="'+k+'"'+(k?'':' disabled')+' aria-label="Omhoog">↑</button><button type="button" class="btn sm" data-sj="neer" data-k="'+k+'"'+(k<e.items.length-1?'':' disabled')+' aria-label="Omlaag">↓</button><button type="button" class="btn sm" data-sj="uit" data-k="'+k+'" aria-label="Weghalen">✕</button></span></li>'}).join('')+'</ol>'+
    (e.items.length?'':'<p class="note">Nog leeg. Voeg hieronder hoofdstukken toe.</p>')+
    '<div class="row" style="gap:8px;align-items:flex-end;flex-wrap:wrap"><div class="field" style="margin:0;flex:1;min-width:220px"><label for="sjAdd">Toevoegen</label><select id="sjAdd">'+(vrijH.length?'<optgroup label="Theoriehoofdstukken">'+vrijH.map(x=>'<option value="h:'+x.id+'">'+esc(x.n)+'</option>').join('')+'</optgroup>':'')+(vrijM.length?'<optgroup label="Extra modules van '+esc(STAD_NAAM[st]||st)+'">'+vrijM.map(x=>'<option value="m:'+x.id+'">'+esc(x.n)+'</option>').join('')+'</optgroup>':'')+'</select></div><button type="button" class="btn" data-sj="add"'+(vrijH.length||vrijM.length?'':' disabled')+'>Toevoegen</button><button type="button" class="btn soft" data-sj="nieuwmod">+ Nieuwe extra module maken</button></div>'+
    '<p class="note">De eindtoets gaat over de theoriehoofdstukken in dit sjabloon. Extra modules hebben een eigen les en quiz en staan op hun plek in het leerpad.</p>'+
    '<h3>Groepen</h3>'+(groepen.length?'<div class="sjchk">'+groepen.map(g=>'<label class="chk"><input type="checkbox" data-sjg="'+g.id+'"'+(e.groepen.has(g.id)?' checked':'')+'> '+esc(g.naam)+(g.sjabloon_id&&g.sjabloon_id!==e.id?' <small>(nu: '+esc(sjNaam(APP.sjAll.find(s=>s.id===g.sjabloon_id)))+')</small>':'')+'</label>').join('')+'</div>':'<p class="note">Nog geen groepen in dit gebied.</p>')+
    '<h3>Kandidaten</h3>'+(kand.length?'<p class="note">Een eigen sjabloon gaat voor het sjabloon van de groep.</p><div class="sjchk">'+kand.map(r=>'<label class="chk"><input type="checkbox" data-sjk="'+r.id+'"'+(e.kand.has(r.id)?' checked':'')+'> '+esc(r.naam)+(r.sjabloon_id&&r.sjabloon_id!==e.id?' <small>(nu: '+esc(sjNaam(APP.sjAll.find(s=>s.id===r.sjabloon_id)))+')</small>':'')+'</label>').join('')+'</div>':'<p class="note">Nog geen kandidaten in dit gebied.</p>')+
    '<div class="row" style="gap:8px;margin-top:14px"><button type="button" class="btn primary" data-sj="opslaan">Opslaan</button><button type="button" class="btn" data-sj="voorbeeld-edit">Voorbeeld bekijken</button><button type="button" class="btn soft" data-sj="annuleer">Annuleren</button></div></section>';
  return h}
function sjLees(){const e=SJ.edit;if(!e||!$('#sjForm'))return e;e.naam=$('#sjNaam').value.trim().replace(/\s+/g,' ');e.standaard=$('#sjStd').checked;
  e.kand=new Set([...document.querySelectorAll('[data-sjk]')].filter(x=>x.checked).map(x=>x.dataset.sjk));e.groepen=new Set([...document.querySelectorAll('[data-sjg]')].filter(x=>x.checked).map(x=>x.dataset.sjg));return e}
function sjStart(t,st){SJ.st=st;SJ.edit={id:t?t.id:null,naam:t?t.naam:'',standaard:t?!!t.standaard:!APP.sjAll.some(s=>s.gebied===st&&s.standaard),items:t?(t.items||[]).map(i=>({t:i.t,id:i.id})):sjItemsAlle(),
  kand:new Set(t?APP.roster.filter(r=>r.sjabloon_id===t.id).map(r=>r.id):[]),groepen:new Set(t?(APP.groepen||[]).filter(g=>g.sjabloon_id===t.id).map(g=>g.id):[])}}
const sjItemsAlle=()=>LEER_ALL.map(c=>({t:'h',id:c.id}));
async function sjOpslaan(){const e=sjLees(),st=SJ.st;if(!e.naam){toast('Geef het sjabloon een naam.',true);return}
  const mods=(APP.meMods||{})[st]||[];const items=e.items.filter(i=>sjItemNaam(i,mods));if(!items.some(i=>i.t==='h')){toast('Kies minstens één theoriehoofdstuk; de eindtoets gaat over de hoofdstukken.',true);return}
  const id=e.id||sjNieuwId();let res;
  if(e.standaard){res=await APP.sb.from('leer_sjablonen').update({standaard:false}).eq('gebied',st).eq('standaard',true);if(res.error){toast(foutTekst(res.error),true);return}}
  const row={naam:e.naam,items,standaard:!!e.standaard,bijgewerkt:nowIso()};
  res=e.id?await APP.sb.from('leer_sjablonen').update(row).eq('id',id):await APP.sb.from('leer_sjablonen').insert(Object.assign({id,gebied:st},row));if(res.error){toast(foutTekst(res.error),true);return}
  const zet=async(tabel,lijst,gekozen)=>{for(const x of lijst){const nu=x.sjabloon_id===id,moet=gekozen.has(x.id);if(nu===moet)continue;const r=await APP.sb.from(tabel).update({sjabloon_id:moet?id:null}).eq('id',x.id);if(r.error)throw r.error}};
  try{await zet('leden',APP.roster.filter(r=>r.rol==='kandidaat'&&(r.stad||'amsterdam')===st),e.kand);await zet('groepen',(APP.groepen||[]).filter(g=>(g.stad||'amsterdam')===st),e.groepen)}catch(err){toast(foutTekst(err,'Toewijzen'),true)}
  SJ.edit=null;await sjLaadAlles();await loadGroepen();toast('Sjabloon '+e.naam+' opgeslagen');await loadRoster()}
async function sjVoorbeeld(t){await openLeerPreview(t||null)}
document.addEventListener('change',e=>{if(e.target.id==='sjSt'){SJ.st=e.target.value;SJ.edit=null;renderGebiedBouwer()}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-sj]');if(!b||!APP.isStaff)return;const a=b.dataset.sj,st=SJ.st||CITY.id;const t=b.dataset.id?APP.sjAll.find(s=>s.id===b.dataset.id):null;
  if(a==='nieuw'){sjStart(null,st);renderGebiedBouwer();return}
  if(a==='bewerk'&&t){sjStart(t,t.gebied);renderGebiedBouwer();return}
  if(a==='annuleer'){SJ.edit=null;renderGebiedBouwer();return}
  if(a==='voorbeeld'){sjVoorbeeld(t);return}
  if(a==='voorbeeld-edit'){const e=sjLees();sjVoorbeeld({id:e.id,naam:e.naam||'Voorbeeld',gebied:st,items:e.items});return}
  if(['op','neer','uit','add'].includes(a)){const e=sjLees();const k=+b.dataset.k;
    if(a==='op'&&k>0)[e.items[k-1],e.items[k]]=[e.items[k],e.items[k-1]];
    if(a==='neer'&&k<e.items.length-1)[e.items[k+1],e.items[k]]=[e.items[k],e.items[k+1]];
    if(a==='uit')e.items.splice(k,1);
    if(a==='add'){const v=($('#sjAdd')||{}).value;if(v){const [tt,id]=[v.slice(0,1),v.slice(2)];e.items.push({t:tt,id})}}
    renderGebiedBouwer();return}
  if(a==='opslaan'){b.disabled=true;await sjOpslaan();return}
  if(a==='nieuwmod'){const e=sjLees();APP.sjTerug=true;APP.gbTab='modules';ME.st=st;ME.edit=meNieuw('hoofdstuk');renderGebiedBouwer();toast('Maak de module, sla hem op en kies daarna in je sjabloon “Toevoegen”.');return}
  if(a==='std'&&t){let r=await APP.sb.from('leer_sjablonen').update({standaard:false}).eq('gebied',t.gebied).eq('standaard',true);if(!r.error)r=await APP.sb.from('leer_sjablonen').update({standaard:true}).eq('id',t.id);if(r.error){toast(foutTekst(r.error),true);return}await sjLaadAlles();toast(t.naam+' is nu de standaard');renderGebiedBouwer();return}
  if(a==='weg'&&t){if(!(await confirmBox('Sjabloon verwijderen?','Kandidaten en groepen met “'+t.naam+'” krijgen weer het standaardsjabloon van het gebied. Hun voortgang blijft bewaard.','Verwijderen')))return;const r=await APP.sb.from('leer_sjablonen').delete().eq('id',t.id);if(r.error){toast(foutTekst(r.error),true);return}await sjLaadAlles();await loadGroepen();toast('Sjabloon verwijderd');await loadRoster();return}});
/* ⋯ → Leeromgeving: welke onderdelen (SOR, interne trainingen) en welk sjabloon voor één kandidaat */
async function sjKiesVoor(r){const st=r.stad||'amsterdam';const sjs=(APP.sjAll||[]).filter(s=>s.gebied===st);const heeft=new Set(trLijst(r));
  const auto=sjVan(Object.assign({},r,{sjabloon_id:null}));
  const body='<p class="note">Kies wat '+esc(r.naam)+' in de leeromgeving krijgt. Bestaande voortgang blijft bewaard.</p><div class="klist">'+TR_KEUZE.map(k=>'<label class="kopt"><input type="checkbox" data-trk="'+k[0]+'"'+(heeft.has(k[0])?' checked':'')+'> <span><b>'+esc(k[1])+'</b> <small>'+esc(k[2])+'</small></span></label>').join('')+'</div>'+
    (APP.sjDb?'<div class="field" id="sjKiesVeld"><label for="sjKies">Sjabloon voor de SOR-theorie</label><select id="sjKies"><option value="">Automatisch: '+esc(sjNaam(auto))+'</option>'+sjs.map(s=>'<option value="'+s.id+'"'+(r.sjabloon_id===s.id?' selected':'')+'>'+esc(s.naam)+'</option>').join('')+'</select><p class="note">Automatisch = het sjabloon van de groep, anders de standaard van '+esc(STAD_NAAM[st]||st)+'. Sjablonen beheer je onder Leeromgeving → Sjablonen.</p></div>':'');
  const y=await modalBox('Leeromgeving van '+r.naam,'',body,'Opslaan','Annuleren');if(!y)return;
  const tr=TR_KEUZE.map(k=>k[0]).filter(k=>{const c=document.querySelector('[data-trk="'+k+'"]');return c&&c.checked});if(!tr.length){toast('Kies minstens één onderdeel.',true);return}
  const patch={trainingen:tr};if($('#sjKies'))patch.sjabloon_id=$('#sjKies').value||null;
  let {error}=await APP.sb.from('leden').update(patch).eq('id',r.id);
  if(error&&dbOntbreekt(error)){toast(foutTekst(error),true);return}if(error){toast(foutTekst(error),true);return}
  toast('Leeromgeving van '+r.naam+' opgeslagen');loadRoster()}
/* interne trainingen (gegenereerd door training/maak_kvb.py; media in training/kvb -> assets/training/kvb) */
const TRAININGEN={kvb:{"id": "kvb", "titel": "Schipper KVB – Basic Training", "kort": "Online voorbereiding voor de praktijktraining op de sloep.", "pass": 0.8, "secties": [{"t": "Introductie", "units": [{"soort": "tekst", "titel": "Schipper KVB Introductie", "kop": "Introductie", "tekst": "Welkom bij de Schipper KVB - Basic Training! Deze online training is bedoeld om je voor te bereiden op de praktijktraining op de boot.\n\nJe kunt met de knoppen **Volgende** en **Vorige** onderaan heen en weer navigeren tussen de verschillende onderdelen.\n\nDe training eindigt met een toets; deze moet je halen om de training te voltooien. Je kunt hem altijd opnieuw doen als het niet gelukt is.\n\nVeel plezier!", "img": "ebook_ba9e35b5.jpg", "id": "u01"}, {"soort": "video", "titel": "Flagship Introduction Video", "src": "video_introductie.mp4", "poster": "poster_introductie.jpg", "duur": "3:11", "id": "u02"}]}, {"t": "Training Syllabus", "units": [{"soort": "pdf", "titel": "Syllabus KVB Basic Training", "paginas": ["p1-1.webp", "p1-2.webp", "p1-3.webp", "p1-4.webp"], "pdf": "kvb_pdf_1_syllabus.pdf", "id": "u03"}]}, {"t": "In de Haven", "units": [{"soort": "tekst", "titel": "De Haven", "kop": "De Haven", "tekst": "Je werkdag begint in de Haven. Hier haal je je boot op en loop je na of alles klaar is voor vertrek.\n\nZolang je in de haven bent is de Havendienst je aanspreekpunt. Zij hebben de boot klaargemaakt, weten hoe laat je moet vertrekken en weten of er nog iets mist op je boot.\n\nVolg in de haven ten alle tijde de instructies van het havenpersoneel op en overleg als er iets is. Zodra je bent vertrokken is OPS pas je aanspreekpunt.", "img": "ebook_6f19e411.jpg", "id": "u04"}, {"soort": "pdf", "titel": "Aankomst en Vertrek", "paginas": ["p2-1.webp", "p2-2.webp", "p2-3.webp", "p2-4.webp", "p2-5.webp", "p2-6.webp", "p2-7.webp"], "pdf": "kvb_pdf_2_aankomst_vertrek.pdf", "id": "u05"}, {"soort": "tekst", "titel": "Note", "kop": "Alles mee?", "tekst": "Mocht er iets niet aanwezig zijn, geef dat dan meteen aan bij de Havendienst. Zij zullen je helpen.\n\nNogmaals: jij bent als schipper verantwoordelijk voor de boot. Mocht Waternet of Handhaving je aanhouden moet je precies aan kunnen wijzen waar alles ligt!", "img": "ebook_9b523e93.jpg", "id": "u06"}, {"soort": "toets", "titel": "Tussentijdse toets: In de Haven", "vragen": [{"t": "mc", "q": "Je komt aan bij de haven, en ziet dat je boot niet goed geladen is. Wat doe je?", "o": ["OPS bellen", "Samen met het havenpersoneel op zoek naar een oplossing", "Je kan prima een extra dag met een deels lege batterij varen, niks aan de hand"], "g": [1], "u": "Pas als je de haven uit bent, en er is iets aan de hand, bel je OPS. Daarvoor los je alles op met het havenpersoneel (eventueel in samenwerking met OPS). Je vertrekt nooit zomaar met een niet goed geladen boot!"}, {"t": "mc", "q": "Wanneer begint het opruimen van de boot na je shift?", "o": ["Meteen bij het terugvaren naar de haven", "Bij de stockboot", "Als de boot weer op z'n plek ligt"], "g": [0], "u": "Je bent samen met je host verantwoordelijk voor het opruimen van je boot. Dit begint al tijdens het terugvaren naar de haven. Spreek je host erop aan om op tijd te beginnen met opruimen."}, {"t": "mc", "q": "Wanneer vaar je langs de stockboot bij vertrek?", "o": ["Alleen op warme dagen", "Alleen als je bepaalde drank aan boord mist", "Altijd"], "g": [2], "u": "Bij vertrek vaar je ALTIJD langs de stockboot. Hier krijg je alle verse producten aan boord voor je dag."}, {"t": "mcma", "q": "Wat pak je uit de Ark voor vertrek? (meerdere antwoorden mogelijk)", "o": ["De Zwarte Map van jouw boot", "De pikhaak", "Een zwemvest voor alle bemanning aan boord (dus ook voor je host)", "Koffie (als je hier zin in hebt natuurlijk)", "De uitgeprinte Checklist voor vertrek + clipboard"], "g": [0, 2, 3, 4], "u": "Je pakt ALTIJD de zwarte map van je boot, de checklist en zwemvesten voor alle bemanningsleden. Als je zin hebt in koffie is dat ook te halen bij de Ark."}, {"t": "mc", "q": "Hoeveel volt moet je boot minimaal hebben voor vertrek?", "o": ["45 volt bij vol gas", "45 volt in neutraal", "51 volt bij vol gas", "51 volt in neutraal"], "g": [3], "u": "Je checkt het voltage alleen als je boot in neutraal staat. Dit voltage moet boven de 51 volt liggen."}], "id": "u07"}]}, {"t": "Manoeuvreren", "units": [{"soort": "tekst", "titel": "Theorie: varen op een open sloep", "kop": "Theorie", "tekst": "De volgende theorie gaat over de basis manoeuvres met een open sloep. Dit is het type sloep waar we bij Flagship Amsterdam het meeste mee varen.\n\nWe zullen deze manoeuvres ook allemaal behandelen in de praktijktraining.", "img": "ebook_81279649.jpg", "id": "u08"}, {"soort": "pdf", "titel": "Aanmeren, afmeren en haakse bocht", "paginas": ["p3-1.webp", "p3-2.webp"], "pdf": "kvb_pdf_3_manoeuvreren.pdf", "id": "u09"}, {"soort": "toets", "titel": "Tussentijdse toets: Manoeuvreren", "vragen": [{"t": "mc", "q": "Wat is de ideale hoek van aan komen varen bij het aanleggen?", "o": ["90 graden", "60 graden", "45 graden"], "g": [2], "u": "De ideale hoek om aan te komen varen is 45 graden."}, {"t": "mc", "q": "Je hebt een rechtsdraaiende schroef. Wat gebeurt er met de boot als je de boot in z’n achteruit zet?", "o": ["De boot trekt met de kont naar links en dus met de neus naar rechts.", "De boot trekt met de kont naar rechts en dus met de neus naar links.", "Niks, de schroefas in diagonaal geacclimatiseerd", "Dan gaat de boot alleen recht achteruit"], "g": [0], "u": "Een rechtsdraaiende schroef zorgt ervoor dat de kont naar links trekt, waardoor de neus automatisch wat naar rechts gaat."}, {"t": "mc", "q": "Hoe bereik je een zo kort mogelijke bocht met een sloep?", "o": ["1) Hard aan komen varen, 2) insturen, 3) vol gas", "1) Rustig aan komen varen, 2) insturen, 3) weinig gas geven", "1) Rustig aan komen varen, 2) insturen, 3) veel gas geven", "1) Boot stil leggen, 2) insturen, 3) een beetje gas", "1) Boot stil leggen, 2) insturen, 3) veel gas"], "g": [3], "u": "De kleinste draaicirkel van een sloep ontstaat wanneer deze VOLLEDIG stil ligt. Ook draai je met meer gas misschien wel sneller, maar heb je ook meer voorwaartse snelheid. Hierdoor werkt het beter om minder gas te geven."}, {"t": "mcma", "q": "Hoe ga je met drift om? (meerdere antwoorden mogelijk)", "o": ["Later terugsturen dan verwacht", "Binnenbocht aanhouden", "Extra gas", "Achterkant van de boot in de gaten houden"], "g": [0, 1, 3], "u": "Extra gas zorgt er NIET voor dat de boot minder last heeft van drift. Alle andere opties zijn wel manieren om er goed mee om te gaan."}, {"t": "mc", "q": "Hoe vaar je weg van de kade met een volle boot?", "o": ["Afduwen", "Gewoon insturen en gas geven", "Achterkant weg van de kade, ruimte creeën, wegvaren"], "g": [2], "u": "Wanneer de boot volledig vol zit, is afduwen zinloos. Ook ligt je draaipunt van de boot zo dat de kont tegen de kade aankomt bij het \"normaal\" wegvaren."}], "id": "u10"}]}, {"t": "Route, Marifoon & AIS", "units": [{"soort": "tekst", "titel": "De Marifoon", "kop": "De Marifoon", "tekst": "In dit hoofdstuk leggen we je alles uit over de Marifoon!\n\nElk schip dat met passagiers vaart in de grachten van Amsterdam is uitgerust met tenminste één marifoon. In de grachten communiceren we op kanaal 10, op de Amstel op kanaal 69.\n\nHet uitluisteren van je marifoon is wettelijk verplicht. In de grachten van Amsterdam gebruiken we omroepen over de marifoon om een actie aan te kondigen en te communiceren met andere schippers.", "img": "ebook_59257b25.jpg", "id": "u11"}, {"soort": "video", "titel": "Video: Marifoon met Max", "src": "video_marifoon.mp4", "poster": "poster_marifoon.jpg", "duur": "2:46", "id": "u12"}, {"soort": "pdf", "titel": "Marifoon & AIS", "paginas": ["p4-1.webp", "p4-2.webp", "p4-3.webp", "p4-4.webp", "p4-5.webp", "p4-6.webp", "p4-7.webp", "p4-8.webp"], "pdf": "kvb_pdf_4_marifoon_ais.pdf", "id": "u13"}, {"soort": "tekst", "titel": "Note", "kop": "Nog 2 dingen:", "tekst": "1. Je kunt via de marifoon ook 'gewoon' communiceren met andere schippers als dat nodig is voor de situatie, maar hou het kort en zakelijk.\n2. Pleziervaart heeft vaak geen marifoon; het kan dus altijd voorkomen dat je ineens een boot tegenkomt, ook al hoorde je niets over de marifoon!", "img": "ebook_9b523e93.jpg", "id": "u14"}, {"soort": "tekst", "titel": "Op Tijd Varen", "kop": "Op Tijd Varen", "tekst": "Op de juiste tijd aankomen en vertrekken is van groot belang! Boten wisselen elkaar af, en tickets worden op gezette tijden geboekt.\n\n1 boot die 5 minuten te laat komt kan een hele dag alle boten laten achterlopen!\n\nDe volgende kaartjes geven aan wanneer je waar moet zijn om op tijd te komen.\n\nToch vertraagd? Meld dit in de dagapp. Dan kan het kadepersoneel hier rekening mee houden.", "img": "ebook_6da27458.jpg", "id": "u15"}, {"soort": "pdf", "titel": "Route & Tijdsschema", "paginas": ["p5-1.webp", "p5-2.webp"], "pdf": "kvb_pdf_5_route_tijdschema.pdf", "id": "u16"}, {"soort": "toets", "titel": "Tussentijdse toets: Route, Marifoon & AIS", "vragen": [{"t": "mcma", "q": "Wat is de opbouw van een marifoonbericht? Vul aan.\n(meerdere antwoorden mogelijk)\n\"Naam boot – naam huidige gracht – ...", "o": ["\"...naar welke gracht\"", "\"...heeft haast wegwezen allemaal\"", "\"...passeert welke gracht – richting\"", "\"...kruist welke gracht – richting\"", "\"...gaat nu oversteken\""], "g": [0, 2, 3], "u": ""}, {"t": "mc", "q": "Welk bericht stuur je in de volgende situatie op de marifoon? Je gaat stuurboord uit.\nDe bootnaam die voor het eigen schip gebruikt mag worden is 'Flagship'. De boot is oranje (met stuurwiel).", "o": ["\"Flagship op de Leidse gaat naar rechts\"", "\"Flagship op de Leidsegracht gaat de Keizersgracht op richting de Brouwersgracht.\"", "\"Flagship op de Keizersgracht gaat de Leidsegracht op richting de Brouwersgracht.\"", "\"Flagship naar Keizersgracht.\""], "g": [1], "u": "", "img": "img_01.webp"}, {"t": "mc", "q": "Je vaart op de Brouwersgracht richting de Prinsengracht. Wat meld je?", "o": ["Flagship – Brouwers – voor de keizers langs – Richting de Prinsen.", "Flagship – Brouwers – Keizers", "Flagship – Heren – Prinsen", "Brouwers - Prinsen"], "g": [0], "u": "Flagship – Brouwers – Passeert de keizers – Richting de Prinsen zou ook goed zijn. \nBerichten van schepen die jouw kant op komen (en waar je dus actief naar moet luisteren) zouden kunnen zijn:\n• (...) Korte Prinsen - Brouwers\n• (...) Keizers - Brouwer richting Haarlemmer\n• (...) Keizers - Brouwers richting Prinsen", "img": "img_02.webp"}, {"t": "mc", "q": "Je vaart op de Prinsengracht en wilt graag doorvaren op dezelfde gracht. Wat meld je?", "o": ["Niks", "Flagship – Prinsengracht - Reguliersgracht", "Flagship – Regulier - Prinsen - Amstel", "Flagship – Prinsengracht kruist de Reguliersgracht"], "g": [3], "u": "Er zijn schippers die vinden dat je hier helemaal niet hoeft om te roepen. Wij vinden van wel. \nBerichten van schepen die jouw kant op komen (en waar je dus actief naar moet luisteren) zouden kunnen zijn:\n• (...) Reguliers - Prinsen", "img": "img_03.webp"}, {"t": "mc", "q": "Je wilt op de Herengracht blijven. Wat meld je?", "o": ["Flagship – Thorbecke Bocht of Thorbecke Burgemeester", "Flagship – Thorbecke - Amstel", "Flagship – Heren over de Reguliers", "Flagship – Heren kruist de Reguliers"], "g": [0], "u": "Dit is een van de drukste en moeilijkste kruispunten van Amsterdam. Luister hier ruim van te voren hoe het er aan toe gaat. \nBerichten van schepen die jouw kant op komen (en waar je dus actief naar moet luisteren) zouden kunnen zijn:\n• (...) Thorbecke - Amstel \n• (...) Regulier - Thorbecke - Amstel \nEen schip dat op jou wacht aan de andere kant zal aan zijn bakboord voorsorteren. Je passeert elkaar dus stuurboord-stuurboord.", "img": "img_04.webp"}], "id": "u17"}]}, {"t": "Eindtoets", "units": [{"soort": "toets", "titel": "Schipper KVB: Online Eindtoets", "vragen": [{"t": "mc", "q": "Je wilt vanaf je huidige positie doorgaan op dezelfde gracht. Wat meld je?", "o": ["Niks", "Flagship – Leidsegracht – Herengracht", "Flagship – Herengracht – Leidsegracht", "Flagship – Herengracht – voor de leidsegracht langs – richting Brouwersgracht"], "g": [3], "u": "Voordat je de Leidse voorbij gaat is het zaak om in het midden van de gracht, of zelfs aan bakboord voor te sorteren; Een schip dat de Leidse uit komt en richting de Amstel gaat zal stuurboord stuurboord willen, omdat zijn achterschip pas heel laat de Leidse uit kan draaien.\nBerichten van schepen die jouw kant op komen (en waar je dus actief naar moet luisteren) zouden kunnen zijn:\n• (...) Leidse - Heren richting Amstel (die gaat naar het zuiden en wil stuur-stuur)\n• (...) Leidse - Heren richting Brouwers (die gaat naar het noorden, geef ruimte voor het draaien)", "img": "img_05.webp"}, {"t": "mc", "q": "Je vaart met een aantal boten achter je op de Herengracht. Je wilt vanaf de Herengracht de Leliegracht invaren. Wat zeg je over de Marifoon?", "o": ["Niks", "Flagship op de Herengracht kruist de Leliegracht.", "Flagship op de Leliegracht gaat de Herengracht in.", "Flagship op de Herengracht gaat de Leliegracht in."], "g": [3], "u": "", "img": "img_06.webp"}, {"t": "mcma", "q": "Net als je van de Heren de Lelie in wilt draaien zie je dat er een klein (plezier)bootje zonder marifoon net uit de Leliegracht komt. Wat doe je? (meerdere antwoorden mogelijk)", "o": ["Snel de Leliegracht in om ruimte te maken", "Je gaat zo veel mogelijk stuurboord wal varen en zet gas in neutraal", "Je geeft hem ruimte en gebaart dat ie door mag komen.", "Je schreeuwt op luide toon een waarschuwing naar de andere boten achter je", "Je beukt hem gewoon aan de kant. Oranje gaat voor!"], "g": [1, 2], "u": "", "img": "img_07.webp"}, {"t": "mc", "q": "Je komt aan bij een gedeelde steiger. Je bent netjes op tijd maar je groep staat al te wachten. De opstap plekken worden bezet door andere boten. Wat doe je?", "o": ["Je vraagt over de marifoon: \"Dit is Flagship voor boot y & boot x. Ik wil graag mijn groep ophalen, ze staan er al. Is het mogelijk om dit even snel te doen?\" Wachten op antwoord.", "Je wacht tot de andere boten weg zijn", "Je legt de boot even bij een niet-officiele plek aan en laat je gasten aan boord, ook al wordt het stuntelen. Snelheid gaat voor.", "Je meldt over de marifoon: \"Dit is Flagship voor boot y & boot x. Mijn groep staat er al, jullie liggen daar te niksen, laat me er even bij\""], "g": [0], "u": "", "img": "img_08.webp"}, {"t": "mc", "q": "Je hoort op de radio \"Titanic Leidse kruist Prinsen richting heren.\" Waar kan deze boot zich bevinden?", "o": ["Locatie A", "Locatie B", "Locatie C"], "g": [0], "u": "", "img": "img_09.webp"}, {"t": "mc", "q": "Je wilt bij de dansende huisjes rondgaan. Je hebt een aantal boten achter je en er komen een aantal boten vanaf de andere kant. Wat doe je in deze situatie?", "o": ["Gas er op en zorgen dat je voor de blauwe boot uitkomt", "Je meldt over de marifoon dat je rond wilt gaan maar wacht tot het overige verkeer gepasseerd is.", "Je sorteert voor in het midden van het vaarwater zodat je niemand tot last bent en gaat rond", "Je meldt over de marifoon dat je rond gaat en gaat rond"], "g": [1], "u": "", "img": "img_10.webp"}, {"t": "mc", "q": "Je wilt van de Zwanenburgwal rechtdoor. Wat meld je?", "o": ["Flagship – St. Anthonysluis/Oudeschans – Zwanenburgwal", "Flagship – Zwanenburgwal – St. Anthonysluis/Oudeschans", "Flagship – Raamgracht – Zwanenburgwal", "Navigatielichten uit, hard toeteren en vol gas door de tunnel terwijl je \"Fortunate Son\" van Creedence Clearwater Revival door je marifoon heen blaast en je je Host(ess) op een surfboard achter je aan sleept."], "g": [1], "u": "Berichten van schepen die jouw kant op komen (en waar je dus actief naar moet luisteren) zouden kunnen zijn:\n• (...) Oudeschans - Zwanenburgwal \n• (...) Houtkopers - Antoniesluis - Zwanenburgwal \n• (...) Snoekjesgracht - Antoniesluis - Zwanenburgwal\nHier wordt ook vaak een volgorde onderling gecommuniceerd. Sluit dus pro-actief aan in de 'rij' door je plek te claimen via de marifoon.", "img": "img_11.webp"}, {"t": "mc", "q": "Je hoort op de radio: “Reguliers, Keizers”. Wat doe je?", "o": ["Je vaart rustig door, de boot is niet bij je in de buurt.", "Je zet de boot stil en wacht tot ie de brug uit komt", "Je roept 'Oranje gaat voor!' over de marifoon en geeft gas bij", "Je zegt, \"begrepen, ik wacht op je\" over de marifoon en laat hem voor gaan"], "g": [0], "u": "De boot die je hoort draait dus van de Reguliers de Keizers op, en komt dus jouw kant niet op. \nAndersom zou je wel moeten opletten; als je op de Prinsengracht zit (wel iets verder voor de reguliers dan deze afbeelding) en een boot roept om: (...) Keizer, Reguliers, dan kan het zijn dat ie binnen korte tijd daarna van de Reguliers de Prinsen op wil. Daar krijg jij dan mee te maken.\nOrienteer je dus niet alleen op je eigen gracht, maar hou ook in de gaten wat er in de grachten om je heen gebeurt. Dat kan je later van pas komen.", "img": "img_12.webp"}, {"t": "mc", "q": "Er vaart een boot langzaam voor je, je wilt in overleg met deze boot inhalen. Wat zeg je over de marifoon?", "o": ["Niks, gewoon knallen", "\"Naam eigen boot – naam andere boot, ik ga je inhalen.\"", "\"Naam andere boot - hier naam eigen boot.\" Wanneer er contact is gelegd: \"Ik wil je graag oplopen, is dat goed?\" Wachten op confirmatie.", "\"Naam andere boot.\" Wanneer er contact is gelegd: \"Ik wil je graag oplopen, is dat goed?\" Wachten op confirmatie."], "g": [2], "u": ""}, {"t": "mc", "q": "Je hoort op de Radio: “tweemaal, zwanenburg wal, oude schans”. Waar komen de boten vandaan (locatie A, B of C) en wat doe je?", "o": ["C, rustig doorvaren", "A, even vol gas geven om ruimte te maken", "C, gelijk uit de weg om ze er langs te laten", "B, rustig doorvaren"], "g": [0], "u": "", "img": "img_13.webp"}, {"t": "mc", "q": "Je hoort: “Leidse, Heren, Bakboord uit”. Waar gaat de boot heen?", "o": ["A", "B", "C"], "g": [0], "u": "", "img": "img_14.webp"}, {"t": "mc", "q": "Je vaart over de Herengracht voor de Leidsegracht. Er komt een lange rondvaartboot uit de Leidsegracht. De schipper roept je op over de radio met het volgende bericht: \"Dit is boot x voor de Flagship. Stuur Stuur.\" \nWat bedoelt hij?", "o": ["De schipper wil graag over stuurboord passeren. Je gaat dus aan de linker kant van het vaarwater varen.", "De schipper wil graag over stuurboord passeren. Je gaat dus aan de rechter kant van het vaarwater varen.", "De schipper vindt dat je beter moet sturen", "De schipper heeft een probleem: zijn stuur werkt niet meer."], "g": [0], "u": "", "img": "img_15.webp"}, {"t": "mc", "q": "Je hoort “Brouwers, Haarlemmer”. Waar komt de boot vandaan?", "o": ["A", "B", "C", "C of B"], "g": [2], "u": "", "img": "img_16.webp"}, {"t": "mc", "q": "Je hoort “Brouwers voor de Heren langs, richting Prinsen.” Waar komt de boot deze kruising op straks?", "o": ["A", "B", "C", "Hij is bij op de Herengracht bij de Amstel, dus niet hier"], "g": [0], "u": "", "img": "img_17.webp"}, {"t": "mc", "q": "Je vaart op de Brouwersgracht en wilt richting Centraal Station. Wat zeg je over de Marifoon?", "o": ["Flagship – Brouwersgracht – Haarlemmer", "Flagship – Brouwersgracht – Centraal Station", "Flagship – Brouwersgracht – Singel", "Flagship – Singel – Haarlemmersluis"], "g": [0], "u": "", "img": "img_18.webp"}, {"t": "mc", "q": "Je hoort het volgende bericht:\nWat gaat het schip 'de BZN' doen?", "o": ["2 boten eerst laten, en dan van A naar B", "Van B naar C achter 2 boten aan", "2 boten eerst laten, dan van B naar A", "Van C naar A met 2 boten achter zich aan"], "g": [0], "u": "", "img": "img_19.webp"}, {"t": "mc", "q": "Je hoort het volgende bericht:\nJe vaart bij A en gaat zo de Prinsen op. Is dit bericht dan voor jou relevant?", "o": ["Ja, jij zit ook op de leidse", "Nee, dit is schip B, die vaart achter je", "Nee, dit is schip C, die vaart achter je", "Ja, jij gaat hem tegenkomen bij punt C"], "g": [2], "u": "", "img": "img_20.webp"}, {"t": "mc", "q": "Je hoort het volgende bericht:\nWat gaat dit schip doen?", "o": ["Van A naar B", "Van C naar B", "Van A naar C", "Dat is hier niet"], "g": [1], "u": "", "img": "img_21.webp"}, {"t": "mc", "q": "Je hebt een rechtsdraaiende schroef. Aan welke zijde van je boot kan je het best aanleggen?", "o": ["Stuurboord", "Bakboord"], "g": [1], "u": ""}, {"t": "mc", "q": "Je wilt keren op een gracht. Je moet dit echter doen door te steken. Hoe pak je dit aan? Je hebt een rechtsdraaiende schroef.", "o": ["Je gebruikt de schroefwerking in je voordeel en draait over bakboord.", "Je gebruikt de schroefwerking in je voordeel en draait over stuurboord.", "Je wacht op wind en gebruikt dat in je voordeel", "Je gebruikt de stroming in je voordeel"], "g": [1], "u": "Je gebruikt de schroefwerking in je voordeel door\nrechtsom te draaien. Je stuurt je roer in naar stuurboord en wisselt gas\nvooruit, waardoor er druk op het roer ontstaat en de boot rechts draait, met gas achteruit, wat door de schroefwerking\nzorgt dat de boot met de kont naar links trekt en dus rechtsom verder draait."}, {"t": "mcImage", "q": "Wat is de juiste manier om een lijn vast te zetten op een kikker?", "o": ["Zo", "of zo"], "g": [0], "u": "", "oi": ["img_22.webp", "img_23.webp"]}, {"t": "mcma", "q": "Wat check je ALTIJD voordat je de boot losmaakt van de kant?", "o": ["Functioneren aandrijving", "Of de host aan boord is", "Hoe laat het is", "Functioneren roer", "Of er 2 marifoons op vol volume aanstaan"], "g": [0, 3], "u": ""}, {"t": "mc", "q": "Je hebt je bij een kruispunt gemeld over de marifoon en je hebt goed uitgeluisterd. Je hoort niks, waardoor je denkt veilig over te kunnen steken. Op het laatste moment komt er een boot van stuurboord. Wat doe je?", "o": ["Snel meer gas er op, zodat je nog net voorlangs kan.", "Noodstop, vol in z’n achteruit. Als je elkaar raakt wil je dat met zo min mogelijk snelheid doen.", "Roer om naar links om een aanvaring te voorkomen.", "Vol in z'n achteruit, naar voren rennen en met je handen de andere boot weg duwen."], "g": [1], "u": ""}, {"t": "mcma", "q": "Welke zaken hebben er invloed op de besturing van een boot?", "o": ["Waternet", "Wind", "Stroming", "De prijs van een ticket", "Handhaving", "het aantal Toeristen aan boord"], "g": [1, 2, 5], "u": ""}, {"t": "mc", "q": "Wat wordt er bedoeld met 'open varen'?", "o": ["Varen op een boot zonder dak.", "Een bocht ruim nemen zodat je eventuele tegenvaart goed en op tijd kunt zien.", "Een bocht zo strak mogelijk nemen", "Heel erg vriendelijk zijn tegen schippers van andere rederijen."], "g": [1], "u": ""}], "eind": true, "id": "u18"}]}, {"t": "Einde", "units": [{"soort": "tekst", "titel": "Einde", "kop": "Dat was het!", "tekst": "Goed gedaan! Je bent klaar voor de training op de boot.\n\nTot snel!", "img": "ebook_a3d52c94.jpg", "id": "u19"}]}]}};
/* ---------- interne trainingen (Schipper KVB – Basic Training, overgenomen uit LearnWorlds) ----------
   Wat iemand krijgt staat in leden.trainingen (migratie 019): 'sor' = SOR-traject (theorie + casus), 'kvb' = KVB Basic Training.
   Zonder kolom of waarde: alleen SOR, zoals voorheen. Voortgang staat bij de theorie: theorie.data.x.tr[<training>]. */
const TR_KEUZE=[['sor','SOR-traject','Theorie, casus en voortgang voor praktijktoets 3']].concat(Object.values(TRAININGEN).map(t=>[t.id,t.titel,t.kort]));
const trLijst=r=>{const t=r&&r.trainingen;return Array.isArray(t)&&t.length?t:['sor']};
const heeftSor=r=>trLijst(r).includes('sor');
const trVan=r=>trLijst(r).filter(k=>TRAININGEN[k]);
const trUnits=tr=>tr.secties.flatMap(s=>s.units.map(u=>Object.assign({sectie:s.t},u)));
const trMedia=(tr,f)=>CITY.assets+'assets/training/'+tr.id+'/'+f;
const trLeeg=()=>({gezien:{},toets:{}});
function trSt(id){const d=APP.th&&APP.th.data;if(!d)return trLeeg();d.x=d.x||{};d.x.tr=d.x.tr||{};const s=d.x.tr[id]=d.x.tr[id]||trLeeg();s.gezien=s.gezien||{};s.toets=s.toets||{};return s}
const trStVan=(th,id)=>{const s=th&&th.data&&th.data.x&&th.data.x.tr&&th.data.x.tr[id];return Object.assign(trLeeg(),s||{})};
const trToetsOk=(tr,st,u)=>{const r=st.toets&&st.toets[u.id];return!!(r&&r.van&&r.best/r.van>=tr.pass)};
const trGedaan=(tr,st,u)=>u.soort==='toets'?(u.eind?trToetsOk(tr,st,u):!!(st.toets&&st.toets[u.id])):!!(st.gezien&&st.gezien[u.id]);
function trStand(tr,st){const us=trUnits(tr),n=us.filter(u=>trGedaan(tr,st,u)).length,eind=us.find(u=>u.eind);return{n,van:us.length,pct:Math.round(n/us.length*100),klaar:!!(eind&&trToetsOk(tr,st,eind))}}
const TR_ICO={tekst:'📄',video:'▶️',pdf:'📑',toets:'✅'};
const TR_SOORT={tekst:'Les',video:'Video',pdf:'Document',toets:'Toets'};

/* tegel op de startpagina van de leeromgeving */
function trTegel(tr){const s=trStand(tr,trSt(tr.id));return'<button type="button" class="ltile" data-tract="open" data-tr="'+tr.id+'"><span class="ltile-i" aria-hidden="true">⛵</span><span class="ltile-t"><b>'+esc(tr.titel)+'</b><span>'+esc(tr.kort)+'</span><small>'+(s.klaar?'Afgerond':s.n?s.n+' van '+s.van+' onderdelen gedaan':'Nog niet begonnen')+'</small></span><span class="ltile-go" aria-hidden="true">→</span></button>'}
function trOpen(id,u){LV.v='tr';LV.id=id;LV.u=u==null?null:u;LQ=null;APP.trQ=null;renderLeer();leerScroll();navPush({k:'leer',v:'tr',id,u:LV.u});if(u!=null)trGezien(id,u)}
function trGezien(id,i){const tr=TRAININGEN[id];const u=trUnits(tr)[i];if(!u||u.soort==='toets')return;const st=trSt(id);if(!st.gezien[u.id]){st.gezien[u.id]=nowIso();thSave()}}
function trView(){const tr=TRAININGEN[LV.id];if(!tr)return viewStart();return LV.u==null?trOverzicht(tr):trUnitView(tr,LV.u)}
function trOverzicht(tr){const st=trSt(tr.id),s=trStand(tr,st),us=trUnits(tr);const eerste=us.findIndex(u=>!trGedaan(tr,st,u));
  let h='<div class="lbar"><button type="button" class="btn soft sm" data-lact="start">← Start</button><span class="lcrumb">'+esc(tr.titel)+'</span></div>';
  h+='<section class="lhero"><div class="lhero-t"><div class="eyebrow">Interne training · Flagship Academy</div><h1>'+esc(tr.titel)+'</h1><p>'+esc(tr.kort)+' Je kunt de onderdelen in je eigen tempo doorlopen. De training is afgerond als je de eindtoets hebt gehaald ('+Math.round(tr.pass*100)+'% goed).</p></div>'+
    '<div class="rank"><div class="rank-badge" aria-hidden="true">'+(s.klaar?'✓':s.pct+'%')+'</div><div class="rank-t"><small>Voortgang</small><b>'+(s.klaar?'Afgerond':s.n+' van '+s.van+' onderdelen')+'</b><div class="xpbar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+s.pct+'" aria-label="Voortgang training"><span style="width:'+s.pct+'%"></span></div></div></div></section>';
  h+='<div class="row" style="margin:4px 0 14px"><button type="button" class="btn primary" data-tract="unit" data-i="'+(eerste<0?0:eerste)+'">'+(s.n?(s.klaar?'Opnieuw bekijken':'Ga verder'):'Start de training')+'</button></div>';
  let i=0;h+=tr.secties.map((sec,k)=>'<section class="lsec trsec"><div class="lsec-h"><h2>'+(k+1)+'. '+esc(sec.t)+'</h2></div><ul class="trlist">'+sec.units.map(u=>{const idx=i++;const ok=trGedaan(tr,st,u);const r=u.soort==='toets'&&st.toets[u.id];
    return'<li><button type="button" class="trrow'+(ok?' ok':'')+'" data-tract="unit" data-i="'+idx+'"><span class="tri" aria-hidden="true">'+(ok?'✓':TR_ICO[u.soort])+'</span><span class="trt"><b>'+esc(u.titel)+'</b><small>'+TR_SOORT[u.soort]+(u.duur?' · '+u.duur:'')+(u.soort==='toets'?' · '+u.vragen.length+' vragen'+(r?' · beste score '+Math.round(r.best/r.van*100)+'%':''):'')+(u.eind?' · '+Math.round(tr.pass*100)+'% om te halen':'')+'</small></span></button></li>'}).join('')+'</ul></section>').join('');
  return h}
const trTekst=t=>String(t||'').split(/\n\n+/).map(p=>/^\d\.\s/.test(p)?'<ol>'+p.split('\n').map(l=>'<li>'+fmtT(l.replace(/^\d\.\s*/,''))+'</li>').join('')+'</ol>':'<p>'+fmtT(p).replace(/\n/g,'<br>')+'</p>').join('');
function trUnitView(tr,i){const us=trUnits(tr),u=us[i];if(!u)return trOverzicht(tr);const st=trSt(tr.id);
  let h='<div class="lbar"><button type="button" class="btn soft sm" data-tract="open" data-tr="'+tr.id+'">← '+esc(tr.titel)+'</button><span class="lcrumb">'+esc(u.sectie)+' · '+(i+1)+' van '+us.length+'</span></div><div class="trunit">';
  if(u.soort==='tekst')h+='<article class="trles"><div class="trles-t"><div class="eyebrow">'+esc(u.sectie)+'</div><h1>'+esc(u.kop||u.titel)+'</h1>'+trTekst(u.tekst)+'</div>'+(u.img?'<img src="'+trMedia(tr,u.img)+'" alt="" loading="lazy">':'')+'</article>';
  else if(u.soort==='video')h+='<header class="lhead"><div class="eyebrow">'+esc(u.sectie)+' · video '+esc(u.duur||'')+'</div><h1>'+esc(u.titel)+'</h1></header><video class="trvideo" controls preload="metadata" playsinline poster="'+trMedia(tr,u.poster)+'" src="'+trMedia(tr,u.src)+'"></video>';
  else if(u.soort==='pdf')h+='<header class="lhead"><div class="eyebrow">'+esc(u.sectie)+' · document</div><h1>'+esc(u.titel)+'</h1><p><a class="btn sm" href="'+trMedia(tr,u.pdf)+'" target="_blank" rel="noopener" download>PDF downloaden</a></p></header><div class="trpdf">'+u.paginas.map((p,k)=>'<img src="'+trMedia(tr,p)+'" alt="'+esc(u.titel)+', pagina '+(k+1)+'" loading="lazy">').join('')+'</div>';
  else if(u.soort==='toets')h+=trToets(tr,u,st);
  h+='</div><div class="trnav">'+(i>0?'<button type="button" class="btn" data-tract="unit" data-i="'+(i-1)+'">← Vorige</button>':'<span></span>')+(i<us.length-1?'<button type="button" class="btn primary" data-tract="unit" data-i="'+(i+1)+'">Volgende →</button>':'<button type="button" class="btn primary" data-tract="open" data-tr="'+tr.id+'">Naar het overzicht</button>')+'</div>';
  return h}
/* toets: alle vragen op één pagina; je ziet direct na het kiezen of je antwoord goed is (meerkeuze met meerdere antwoorden: na "Controleer").
   Als alle vragen beantwoord zijn, wordt de score bewaard. */
const trVraagGoed=(q,sel)=>{const a=[...sel].sort().join(','),b=[...q.g].sort().join(',');return a===b};
const trQNieuw=u=>({id:u.id,ans:{},klaar:{}});
function trVraag(tr,q,k,Q){const multi=q.t==='mcma',sel=Q.ans[k]||[],af=!!Q.klaar[k],goed=af&&trVraagGoed(q,sel);
  return'<li class="trq'+(af?(goed?' goed':' fout'):'')+'" data-trk-li="'+k+'"><p class="trqq">'+fmtT(q.q).replace(/\n/g,'<br>')+'</p>'+(q.img?'<img class="trqimg" src="'+trMedia(tr,q.img)+'" alt="Afbeelding bij vraag '+(k+1)+'" loading="lazy">':'')+(multi&&!af?'<small class="note">Meerdere antwoorden mogelijk. Kies alles wat klopt en klik op Controleer.</small>':'')+
    '<div class="tropts'+(q.oi?' img':'')+'">'+q.o.map((o,j)=>{const on=sel.includes(j),juist=q.g.includes(j);return'<label class="tropt'+(on?' on':'')+(af&&juist?' juist':'')+(af&&on&&!juist?' mis':'')+'"><input type="'+(multi?'checkbox':'radio')+'" name="trq'+k+'" data-trq="'+k+'" data-tro="'+j+'"'+(on?' checked':'')+(af?' disabled':'')+'>'+(q.oi?'<img src="'+trMedia(tr,q.oi[j])+'" alt="'+esc(o)+'" loading="lazy">':'')+'<span>'+esc(o)+'</span>'+(af&&juist?'<i class="trmark" aria-label="juist antwoord">✓</i>':af&&on?'<i class="trmark" aria-label="fout">✕</i>':'')+'</label>'}).join('')+'</div>'+
    (multi&&!af?'<div class="row" style="margin-top:8px"><button type="button" class="btn sm primary" data-tract="controleer" data-k="'+k+'"'+(sel.length?'':' disabled')+'>Controleer</button></div>':'')+
    (af?'<div class="trq-u" role="status"><b>'+(goed?'Goed!':'Helaas, niet goed.')+'</b> '+(q.u?fmtT(q.u):(goed?'':'Het juiste antwoord is groen gemarkeerd.'))+'</div>':'')+'</li>'}
function trStandToets(u,Q){const n=u.vragen.length,af=Object.keys(Q.klaar).length,goed=u.vragen.filter((q,k)=>Q.klaar[k]&&trVraagGoed(q,Q.ans[k]||[])).length;return{n,af,goed}}
function trResHtml(tr,u,Q){const s=trStandToets(u,Q);if(s.af<s.n)return'<div class="trteller" id="trTeller">'+s.af+' van '+s.n+' beantwoord · '+s.goed+' goed</div>';
  const ok=s.goed/s.n>=tr.pass;return'<div class="trres '+(ok?'ok':'nok')+'" id="trTeller" role="status"><b>Klaar: '+s.goed+' van '+s.n+' goed ('+Math.round(s.goed/s.n*100)+'%)</b><span>'+(u.eind?(ok?'Gefeliciteerd, je hebt de training afgerond!':'Nog niet gehaald; je hebt '+Math.round(tr.pass*100)+'% nodig. Bekijk de uitleg en probeer het opnieuw.'):(ok?'Goed gedaan.':'Bekijk de uitleg bij de vragen die fout waren.'))+'</span><button type="button" class="btn sm" data-tract="opnieuw">Opnieuw maken</button></div>'}
function trToets(tr,u,st){const Q=APP.trQ&&APP.trQ.id===u.id?APP.trQ:(APP.trQ=trQNieuw(u));const r=st.toets[u.id];
  let h='<header class="lhead"><div class="eyebrow">'+(u.eind?'Afsluiting':esc(u.sectie)+' · tussentijdse toets')+'</div><h1>'+esc(u.titel)+'</h1><p>'+u.vragen.length+' vragen. Na elk antwoord zie je meteen of het goed is.'+(u.eind?' Je hebt '+Math.round(tr.pass*100)+'% goed nodig om de training af te ronden.':'')+(r?' Je beste score tot nu toe: '+Math.round(r.best/r.van*100)+'%.':'')+'</p></header>';
  return h+'<ol class="trqs">'+u.vragen.map((q,k)=>trVraag(tr,q,k,Q)).join('')+'</ol><div id="trResPlek">'+trResHtml(tr,u,Q)+'</div>'}
function trHuidig(){const tr=TRAININGEN[LV.id];const u=tr&&trUnits(tr)[LV.u];return u&&u.soort==='toets'&&APP.trQ&&APP.trQ.id===u.id?{tr,u,Q:APP.trQ}:null}
function trVraagKlaar(k){const c=trHuidig();if(!c)return;const {tr,u,Q}=c;Q.klaar[k]=true;
  const li=document.querySelector('[data-trk-li="'+k+'"]');if(li){li.outerHTML=trVraag(tr,u.vragen[k],k,Q)}
  const plek=$('#trResPlek');if(plek)plek.innerHTML=trResHtml(tr,u,Q);const s=trStandToets(u,Q);
  if(s.af===s.n&&!Q.bewaard){Q.bewaard=true;const st=trSt(tr.id),prev=st.toets[u.id];st.toets[u.id]={best:Math.max(s.goed,prev?prev.best:0),van:s.n,n:(prev?prev.n:0)+1,op:nowIso(),laatste:s.goed};
    if(u.eind&&s.goed/s.n>=tr.pass&&!st.klaar)st.klaar=nowIso();thSave();const res=$('#trTeller');if(res)setTimeout(()=>res.scrollIntoView({behavior:'smooth',block:'center'}),200)}}
document.addEventListener('change',e=>{const t=e.target;if(!t.dataset||t.dataset.trq==null)return;const c=trHuidig();if(!c)return;const k=+t.dataset.trq,j=+t.dataset.tro,Q=c.Q;if(Q.klaar[k])return;
  if(t.type==='radio'){Q.ans[k]=[j];trVraagKlaar(k);return}
  const s=new Set(Q.ans[k]||[]);t.checked?s.add(j):s.delete(j);Q.ans[k]=[...s];t.closest('.tropt').classList.toggle('on',t.checked);const btn=document.querySelector('[data-tract="controleer"][data-k="'+k+'"]');if(btn)btn.disabled=!s.size});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-tract]');if(!b||APP.mode!=='leer')return;const a=b.dataset.tract;
  if(a==='open'){trOpen(b.dataset.tr,null);return}
  if(a==='unit'){trOpen(LV.id,+b.dataset.i);return}
  if(a==='opnieuw'){APP.trQ=null;renderLeer();leerScroll();return}
  if(a==='controleer'){trVraagKlaar(+b.dataset.k);return}});
/* medewerkers: voortgang per kandidaat */
function trPill(r){if(r.rol!=='kandidaat')return'';return trVan(r).map(id=>{const tr=TRAININGEN[id],s=trStand(tr,trStVan(r.th,id));return' <span class="pill '+(s.klaar?'ok':'blue')+'" title="'+esc(tr.titel)+'">'+(id==='kvb'?'KVB':esc(tr.titel))+' '+(s.klaar?'afgerond':s.pct+'%')+'</span>'}).join('')+(heeftSor(r)?'':' <span class="pill unk" title="Geen SOR-traject">Geen SOR</span>')}
/* startpagina voor iemand zonder SOR-traject: alleen de toegewezen trainingen */
function trStart(){const trs=trVan(APP.lid).map(k=>TRAININGEN[k]);let h='<section class="lhero lstart"><div class="lhero-t"><div class="eyebrow">Leeromgeving · Flagship Academy</div><h1>Hoi '+esc(voornaam())+', welkom aan boord</h1><p>Hier vind je je trainingen. Je voortgang wordt automatisch bewaard.</p></div></section>';
  h+=trs.length?'<div class="ltiles">'+trs.map(trTegel).join('')+'</div>':'<p class="note">Er is nog geen training aan je toegewezen. Neem contact op met Flagship Academy.</p>';h+=leerHulpSec(false);return h}
/* beheer: Leeromgeving → Interne trainingen (alleen medewerkers) */
function trBeheer(){const tr=TRAININGEN.kvb;const kand=APP.roster.filter(r=>r.rol==='kandidaat'&&r.status!=='geslaagd').sort((a,b)=>(trVan(b).includes('kvb')-trVan(a).includes('kvb'))||a.naam.localeCompare(b.naam));
  const ingedeeld=kand.filter(r=>trVan(r).includes('kvb'));const us=trUnits(tr);
  let h='<div class="trbeheer"><div class="row" style="justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px"><div><h2 style="margin:0">'+esc(tr.titel)+'</h2><p class="note">'+esc(tr.kort)+' '+tr.secties.length+' hoofdstukken, '+us.length+' onderdelen, '+us.filter(u=>u.soort==='toets').length+' toetsen. Afgerond na de eindtoets ('+Math.round(tr.pass*100)+'% goed). Overgenomen uit LearnWorlds.</p></div><button type="button" class="btn" data-top="tr-view">Voorbeeld bekijken</button></div>';
  h+='<p class="note">Vink aan wie deze training krijgt. Iemand die alleen de training krijgt (zonder SOR-traject) ziet in de leeromgeving alleen de training, geen theorie en geen casus. Dat stel je per persoon in via ⋯ → Leeromgeving en trainingen, of bij Kandidaat toevoegen.</p>';
  if(!kand.length)return h+'<p class="note">Nog geen kandidaten.</p></div>';
  h+='<div class="tbl-wrap"><table class="tbl dtbl"><thead><tr><th>Krijgt training</th><th>Naam</th><th>Vaargebied</th><th>Voortgang</th></tr></thead><tbody>'+kand.map(r=>{const on=trVan(r).includes('kvb');const s=trStand(tr,trStVan(r.th,'kvb'));
    return'<tr><td><input type="checkbox" data-trtoe="'+r.id+'"'+(on?' checked':'')+' aria-label="'+esc(r.naam)+' krijgt de training"></td><td class="c-person"><b>'+esc(r.naam)+'</b>'+(heeftSor(r)?'':' <span class="pill unk">alleen training</span>')+'</td><td data-l="Vaargebied">'+esc(STAD_NAAM[r.stad||'amsterdam']||r.stad||'')+'</td><td data-l="Voortgang">'+(on?(s.klaar?'<span class="pill ok">Afgerond</span>':'<span class="row" style="gap:6px"><span class="pbar sm"><span style="width:'+s.pct+'%"></span></span><span class="num">'+s.n+'/'+s.van+'</span></span>'):'–')+'</td></tr>'}).join('')+'</tbody></table></div>';
  return h+'<div class="row" style="margin-top:10px"><button type="button" class="btn primary" data-trbeheer="opslaan">Opslaan</button><span class="note">'+ingedeeld.length+' van '+kand.length+' kandidaten krijgen de training</span></div></div>'}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-trbeheer]');if(!b||!APP.isStaff)return;b.disabled=true;let n=0;
  try{for(const c of document.querySelectorAll('[data-trtoe]')){const r=APP.roster.find(x=>x.id===c.dataset.trtoe);if(!r)continue;const nu=trVan(r).includes('kvb');if(nu===c.checked)continue;
    let lijst=trLijst(r).filter(k=>k!=='kvb');if(c.checked)lijst=lijst.concat(['kvb']);if(!lijst.length)lijst=['sor'];
    const {error}=await APP.sb.from('leden').update({trainingen:lijst}).eq('id',r.id);if(error)throw error;n++}
    toast(n?'Opgeslagen ('+n+' gewijzigd)':'Niets gewijzigd');await loadRoster()}catch(err){toast(foutTekst(err),true);b.disabled=false}});
/* ---------- AI-conceptfeedback (migratie 017, Edge Function ai-feedback) ----------
   Bij het inleveren laat de casusbouwer de casus analyseren. Het concept is alleen zichtbaar voor
   medewerkers en leermeesters (APP.role==='staff'); de kandidaat ziet het nooit. Pas als een medewerker
   op Overnemen klikt, komt de tekst in de gewone feedback die de kandidaat wel ziet. */
/* Aan of uit via Instellingen (aiAan(), tabel instellingen). Staat het uit, dan gebeurt er niets en is er niets zichtbaar.
   De Edge Function controleert de schakelaar, de API-sleutel en de maandlimiet zelf nog een keer. */
const AI_ZEKER={hoog:'zeker',middel:'redelijk zeker',laag:'twijfel'};
APP.ai=null;APP.aiAll={};APP.aiVoorbeeld={};
function aiExtras(){const out={controles:[],route:null};
  try{const cs=(CHECKS&&CHECKS.length)?CHECKS:checks();out.controles=cs.slice(0,200).map(c=>({stap:c.step,ok:!!c.ok,niveau:c.level,label:c.label}))}catch(e){}
  try{if(R&&R.ok&&R.pts&&R.pts.length>1){const d=duration();out.route={minuten:Math.round(d.total),tegen_eenrichting:R.against||[],te_groot_voor:(R.viol||[]).map(v=>v.nm),
    bruggen:(R.bridges||[]).map((f,i)=>{const s=bridgeStatus(f.br);return{nr:i+1,naam:f.br.nm||f.br.name||f.br.n||'',status:s.t}})}}}catch(e){}
  return out}
async function aiLoad(id){if(!aiAan()||!APP.sb||APP.role!=='staff')return;
  const {data,error}=await APP.sb.from('ai_concept').select('*').eq('kandidaat_id',id).maybeSingle();
  if(APP.target!==id)return;APP.aiDb=!(error&&dbOntbreekt(error));APP.ai=error?null:(data||null);aiPoll(id)}
function aiPoll(id){clearTimeout(APP.aiT);if(!APP.ai||APP.ai.status!=='bezig')return;let n=0;
  const tik=async()=>{if(APP.target!==id||APP.role!=='staff'||n++>75)return;const was=APP.ai&&APP.ai.status;await aiLoad(id);
    if(APP.ai&&APP.ai.status!=='bezig'){if(was==='bezig'&&APP.ai.status==='klaar')toast('AI-conceptfeedback is klaar');if(APP.mode==='edit')renderPanel();return}APP.aiT=setTimeout(tik,4000)};
  APP.aiT=setTimeout(tik,4000)}
/* reden: 'inleveren' (kandidaat), 'openen' (automatisch bij openen door medewerker), 'handmatig' */
async function aiStart(id,reden,stil){if(!aiAan()||!APP.sb||!id)return false;
  try{const {data,error}=await APP.sb.functions.invoke('ai-feedback',{body:Object.assign({kandidaat_id:id,reden},aiExtras())});
    if(error){let j={};try{j=await error.context.json()}catch(e){}
      if(APP.role==='staff'&&APP.target===id){await aiLoad(id);if(APP.mode==='edit')renderPanel()}
      if(!stil)toast(j.error==='niet_ingesteld'?'AI-feedback werkt nog niet: de API-sleutel ontbreekt in Supabase.':j.error==='uitgeschakeld'?'AI-feedback staat uit. Zet het aan bij Instellingen.':j.error==='limiet'?'De maandlimiet voor AI-feedback is bereikt. Verhoog de limiet bij Instellingen of wacht tot volgende maand.':'Conceptfeedback maken is mislukt.',true);return false}
    if(APP.role==='staff'&&APP.target===id){await aiLoad(id);if(APP.mode==='edit')renderPanel()}
    return true}catch(e){if(!stil)toast('Conceptfeedback maken is mislukt.',true);return false}}
/* medewerker opent een ingeleverde casus zonder concept: alsnog laten maken (bijv. als het bij inleveren mislukte) */
function aiAuto(id){if(APP.role!=='staff'||!APP.aiDb||APP.ai)return;if(APP.meta.status!=='ingeleverd')return;aiStart(id,'openen',true)}
function aiVerouderd(){const a=APP.ai;return!!(a&&a.status==='klaar'&&a.casus_bijgewerkt&&APP.meta.bijgewerkt&&new Date(APP.meta.bijgewerkt)-new Date(a.casus_bijgewerkt)>60000)}
async function aiMark(step,val){const a=APP.ai;if(!a)return;a.afgehandeld=Object.assign({},a.afgehandeld||{});if(val)a.afgehandeld[step]=val;else delete a.afgehandeld[step];
  const {error}=await APP.sb.from('ai_concept').update({afgehandeld:a.afgehandeld}).eq('kandidaat_id',APP.target);if(error)toast(foutTekst(error,'Bijwerken'),true)}
function aiOvernemen(step,mode){const a=APP.ai;const s=a&&(step==='algemeen'?{tekst:a.algemeen}:(a.stappen||{})[step]);if(!s)return;const cur=fbStep(step);
  const tekst=mode==='erbij'&&cur&&(cur.tekst||'').trim()?cur.tekst.trim()+'\n\n'+s.tekst:s.tekst;
  setFb(step,step==='algemeen'?{tekst}:{status:s.status||'',tekst});aiMark(step,'over');renderPanel();renderRail()}
/* concept bij een stap, direct onder het feedbackvak van de medewerker */
function aiBox(id){const a=APP.ai;if(!aiAan()||APP.role!=='staff'||!a||id==='controle')return'';
  if(a.status==='bezig')return'<section class="ai-box"><div class="fb-h"><span class="ai-tag">AI</span><b>Concept wordt gemaakt…</b></div><p class="note">De casus wordt geanalyseerd. Dit duurt meestal een minuut.</p></section>';
  if(a.status!=='klaar')return'';const s=(a.stappen||{})[id];if(!s)return'';const af=(a.afgehandeld||{})[id];
  if(af)return'<div class="ai-done"><span class="ai-tag">AI</span> Concept '+(af==='over'?'overgenomen':'genegeerd')+' · <a role="button" tabindex="0" data-ai="terug" data-step-ai="'+id+'">Concept weer tonen</a></div>';
  const cur=fbStep(id);const heeft=cur&&(cur.tekst||'').trim();
  return'<section class="ai-box"><div class="fb-h"><span class="ai-tag">AI</span><b>Conceptfeedback</b>'+(s.status==='ok'?'<span class="pill ok">Akkoord</span>':'<span class="pill acc">Aanpassen</span>')+(s.zekerheid?'<span class="note">'+esc(AI_ZEKER[s.zekerheid]||s.zekerheid)+'</span>':'')+'</div><p>'+esc(s.tekst)+'</p>'+
    '<div class="row"><button type="button" class="btn sm primary" data-ai="over" data-step-ai="'+id+'">'+(heeft?'Vervangen':'Overnemen')+'</button>'+(heeft?'<button type="button" class="btn sm" data-ai="erbij" data-step-ai="'+id+'">Toevoegen</button>':'')+'<button type="button" class="btn sm soft" data-ai="neg" data-step-ai="'+id+'">Negeren</button></div>'+
    '<div class="fb-meta">Alleen zichtbaar voor medewerkers en leermeesters. De kandidaat ziet dit pas als je het overneemt.</div></section>'}
/* overzicht op de stap Controle */
function aiOverzicht(){const a=APP.ai;if(!aiAan()||APP.role!=='staff')return'';
  if(!APP.aiDb)return'<section class="ai-box"><div class="fb-h"><span class="ai-tag">AI</span><b>AI-conceptfeedback</b></div><p class="note">Werkt nog niet: de database moet eerst worden bijgewerkt (database-update 017).</p></section>';
  const knop=(t,cls)=>'<button type="button" class="btn sm '+(cls||'')+'" data-ai="nieuw">'+t+'</button>';
  let h='<section class="ai-box"><div class="fb-h"><span class="ai-tag">AI</span><b>AI-conceptfeedback</b></div>';
  if(!a)h+='<p class="note">'+(APP.meta.status==='ingeleverd'?'Er is nog geen concept.':'Het concept wordt automatisch gemaakt zodra de kandidaat inlevert.')+'</p><div class="row">'+knop('Concept maken','primary')+'</div>';
  else if(a.status==='bezig')h+='<p class="note">Concept wordt gemaakt…</p>';
  else if(a.status==='uit')h+='<p class="note">'+(a.fout==='limiet'?'De maandlimiet voor AI-feedback is bereikt (zie Instellingen).':a.fout==='uitgeschakeld'?'AI-feedback stond uit toen deze casus werd ingeleverd.':'AI-feedback werkt nog niet: de API-sleutel ontbreekt in Supabase.')+'</p><div class="row">'+knop('Opnieuw proberen')+'</div>';
  else if(a.status==='fout')h+='<p class="note">Het concept kon niet worden gemaakt: '+esc(a.fout||'onbekende fout')+'</p><div class="row">'+knop('Opnieuw proberen','primary')+'</div>';
  else{const st=a.stappen||{},af=a.afgehandeld||{};const ids=STEPS.filter(s=>st[s.id]).map(s=>s.id);const open=ids.filter(i=>!af[i]);const aanp=ids.filter(i=>st[i].status==='aanpassen');
    h+='<p class="note">Gemaakt '+esc(fmtDate(a.gemaakt))+(a.voorbeelden?' · vergeleken met '+a.voorbeelden+' goede casus'+(a.voorbeelden>1?'sen':''):' · nog geen voorbeeldcasus beschikbaar')+' · '+aanp.length+' van '+ids.length+' stappen aanpassen · '+open.length+' nog te beoordelen</p>'+
      (aiVerouderd()?'<p class="note"><b>Let op:</b> de kandidaat heeft de casus na dit concept nog gewijzigd.</p>':'')+
      (a.algemeen&&!af.algemeen?'<div class="ai-alg"><b>Algemeen</b><p>'+esc(a.algemeen)+'</p><div class="row"><button type="button" class="btn sm" data-ai="over" data-step-ai="algemeen">In algemene feedback zetten</button><button type="button" class="btn sm soft" data-ai="neg" data-step-ai="algemeen">Negeren</button></div></div>':'')+
      '<div class="row">'+(open.length?'<button type="button" class="btn sm primary" data-ai="alles">Alle open concepten overnemen</button>':'')+knop('Concept vernieuwen')+'</div>'+
      '<ul class="ai-lijst">'+ids.map(i=>{const s=STEPS.find(x=>x.id===i);return'<li><a data-step="'+i+'" role="button" tabindex="0">'+esc(s.t)+'</a> '+(st[i].status==='ok'?'<span class="pill ok">Akkoord</span>':'<span class="pill acc">Aanpassen</span>')+(af[i]?' <span class="note">'+(af[i]==='over'?'overgenomen':'genegeerd')+'</span>':'')+'</li>'}).join('')+'</ul>'}
  return h+'<div class="fb-meta">Alleen zichtbaar voor medewerkers en leermeesters.</div></section>'}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ai]');if(!b||APP.role!=='staff'||!APP.target)return;e.preventDefault();const act=b.dataset.ai,step=b.dataset.stepAi;
  if(act==='over'||act==='erbij'){aiOvernemen(step,act);return}
  if(act==='neg'){await aiMark(step,'neg');renderPanel();return}
  if(act==='terug'){await aiMark(step,'');renderPanel();return}
  if(act==='alles'){const a=APP.ai;if(!a)return;const st=a.stappen||{},af=a.afgehandeld||{};let n=0,over=0;
    STEPS.forEach(s=>{const c=st[s.id];if(!c||af[s.id])return;const cur=fbStep(s.id);if(cur&&(cur.tekst||'').trim()){over++;return}setFb(s.id,{status:c.status||'',tekst:c.tekst});a.afgehandeld=Object.assign({},a.afgehandeld||{},{[s.id]:'over'});n++});
    if(n)await aiMark('_',null);renderPanel();renderRail();toast(n+' concept'+(n===1?'':'en')+' overgenomen'+(over?'; '+over+' stap'+(over===1?'':'pen')+' met eigen feedback overgeslagen':'')+'. Controleer de feedback en mail hem daarna naar de kandidaat.');return}
  if(act==='nieuw'){b.disabled=true;const ok=await aiStart(APP.target,'handmatig',false);if(ok)toast('Concept wordt gemaakt…');return}});
/* overzicht: labels per kandidaat */
async function aiLoadAll(){APP.aiAll={};APP.aiVoorbeeld={};if(!aiAan()||!APP.sb||!(APP.isStaff||APP.isLm))return;
  const [c,v]=await Promise.all([APP.sb.from('ai_concept').select('kandidaat_id,status,gemaakt'),APP.isStaff?APP.sb.from('ai_voorbeeld').select('kandidaat_id'):Promise.resolve({data:[]})]);
  if(c&&!c.error)(c.data||[]).forEach(x=>{APP.aiAll[x.kandidaat_id]=x});if(v&&!v.error)(v.data||[]).forEach(x=>{APP.aiVoorbeeld[x.kandidaat_id]=true})}
function aiPill(r){if(r.rol!=='kandidaat')return'';const a=APP.aiAll[r.id];let h='';
  if(a&&a.status==='klaar')h+=' <span class="pill ai" title="Conceptfeedback van de AI staat klaar om te beoordelen">AI-concept</span>';else if(a&&a.status==='bezig')h+=' <span class="pill unk">AI bezig</span>';
  if(APP.aiVoorbeeld[r.id])h+=' <span class="pill ok" title="Deze casus dient als voorbeeld voor de AI">Voorbeeldcasus</span>';return h}
async function aiVoorbeeldZetten(r){const aan=!APP.aiVoorbeeld[r.id];
  const y=await confirmBox(aan?'Als voorbeeldcasus gebruiken?':'Niet meer als voorbeeld gebruiken?',aan?'De AI vergelijkt nieuwe casussen met deze casus van '+r.naam+'. Kies alleen een goede, goedgekeurde casus. Naam, geboortedatum, CBR-nummer en foto’s gaan niet mee.':'De casus van '+r.naam+' wordt niet meer als voorbeeld gebruikt.',aan?'Gebruiken':'Stoppen');if(!y)return;
  const {error}=aan?await APP.sb.from('ai_voorbeeld').insert({kandidaat_id:r.id}):await APP.sb.from('ai_voorbeeld').delete().eq('kandidaat_id',r.id);
  if(error){toast(foutTekst(error,'Opslaan'),true);return}toast(aan?'Casus van '+r.naam+' is nu een voorbeeldcasus':'Voorbeeldcasus uitgezet');loadRoster()}

